def refs(): return [{**s,"locator":f"{s['title']}；僅取人物描述、關係與生活資訊判讀能力方向。","observedPattern":"參照公開英文試題的人物短文、細節擷取與比較推論層次；題幹、選項與答案全部重新編寫。","reuseDecision":"pattern-only","status":"recorded","subject":"english","locatorLevel":"paper"} for s in SOURCES]
def make(i,prompt,opts,ans,exp,strat,steps,diff): return {"id":f"question-english-performance-2-iv-4-{i}","subject":"english","type":"single-choice","prompt":prompt,"options":[{"id":k,"text":v} for k,v in opts.items()],"knowledgeIds":[KG],"difficulty":diff,"answer":{"value":ans,"explanation":exp},"provenance":{"origin":"original","license":"All rights reserved","sourceUrl":SOURCES[0]["url"],"sourceLocator":"三份公開英文試題僅供能力方向研究；未複製原題、選項、文章或答案。","authoringNote":"依官方課綱 KG 與公開英文試題的人物描述能力方向獨立編寫；待第二輪 AI／Terra 內容複核。"},"reviewStatus":"draft","updatedAt":"2026-09-09","lessonId":LESSON,"examPatternRefs":refs(),"solutionStrategy":strat,"solutionSteps":steps}
Q=[
make(1,"Maya is my older sister. She has short hair, wears glasses, and loves drawing animals. Which statement is correct?",{"A":"Maya is an older sister who likes drawing animals.","B":"Maya is a younger brother who plays soccer.","C":"Maya has long hair and dislikes art.","D":"Maya is a teacher from another school."},"A","The description says she is an older sister, has short hair and glasses, and enjoys drawing animals.","Match the relationship and hobby directly stated, then ignore details that contradict the description.",["Identify Maya's relationship: older sister.","Record her appearance: short hair and glasses.","Record her interest: drawing animals.","Compare each option with all three facts.","Choose A because it preserves the supported relationship and hobby."],"easy"),
make(2,"Leo is quiet at first, but he tells funny stories after he feels comfortable. What is Leo probably like with close friends?",{"A":"More talkative and humorous","B":"Always angry and silent","C":"Unable to understand stories","D":"Afraid of every friend"},"A","The contrast shows that Leo becomes talkative and funny when he feels comfortable with people.","Use the time/condition contrast at first versus after he feels comfortable to infer the change.",["Notice Leo is quiet at first.","Read what happens after he feels comfortable.","Translate tells funny stories into a personality clue.","Reject anger, inability, and fear because they are unsupported.","Select A because it combines talkative behavior with humor."],"medium"),
make(3,"My cousin Nina practices the violin before breakfast on weekdays, while I practice after dinner. What is different?",{"A":"We practice at different times.","B":"Only Nina practices music.","C":"We practice different instruments.","D":"Nina practices only on weekends."},"A","Both cousins practice violin, but Nina practices before breakfast and the speaker after dinner.","Compare the shared activity first, then focus on the time expressions that differ.",["Identify the shared activity: violin practice.","Locate Nina's time: before breakfast on weekdays.","Locate the speaker's time: after dinner.","Reject choices about instruments and weekend-only practice.","Choose A because time is the only stated difference."],"easy"),
make(4,"Tom helps his grandfather carry groceries every Saturday. What does this detail show about Tom?",{"A":"He is helpful and has a regular family activity.","B":"He never visits his family.","C":"He dislikes all weekend activities.","D":"He carries groceries only at school."},"A","Helping a grandfather every Saturday supports both helpfulness and a regular family routine.","Infer a limited personality trait from the repeated action without adding facts beyond the sentence.",["Identify Tom's action: helping carry groceries.","Identify the person helped: his grandfather.","Notice every Saturday signals a regular routine.","Infer helpfulness, but do not invent unrelated traits.","Select A because it states both supported ideas."],"medium"),
make(5,"Ava and her friend Ben both enjoy science, but Ava likes experiments and Ben prefers reading science books. Which statement is true?",{"A":"They share an interest but prefer different activities.","B":"Only Ben likes science.","C":"Ava never does experiments.","D":"They both dislike science books."},"A","Both enjoy science; the sentence then contrasts experiments with reading books.","Separate a shared trait introduced before but from the different preferences after it.",["Find the shared interest: science.","Find Ava's preferred activity: experiments.","Find Ben's preferred activity: reading science books.","Reject statements that deny the shared interest or reverse a preference.","Choose A because it includes the common point and contrast."],"medium"),
make(6,"My father cooks dinner, and my mother washes the dishes afterward. What is the family doing?",{"A":"Sharing household responsibilities","B":"Preparing for a sports match","C":"Avoiding all housework","D":"Studying two different languages"},"A","Cooking and washing dishes are two family members' different household tasks, so they share responsibilities.","Connect each person's action to the broader household activity.",["Identify the father's task: cooking dinner.","Identify the mother's task: washing dishes afterward.","Recognize both as household responsibilities.","Reject sports, avoidance, and language-study interpretations.","Select A because it summarizes the relationship between the tasks."],"easy"),
make(7,"When Sara's friend makes a mistake in a presentation, Sara waits, smiles, and says, 'You can try that part again.' What quality does Sara show?",{"A":"Patience and encouragement","B":"Impatience and mockery","C":"Confusion about friendship","D":"A desire to end every presentation"},"A","Waiting, smiling, and encouraging a second attempt show patience and supportive behavior.","Use the actions and exact quotation together to infer the quality, rather than judging from the mistake alone.",["List Sara's actions: waits and smiles.","Read her words: You can try that part again.","Interpret the words as support after a mistake.","Reject mockery, confusion, and ending the presentation.","Choose A because both patience and encouragement are evidenced."],"hard"),
make(8,"My younger brother is shorter than me now, but he runs faster. Which comparison is accurate?",{"A":"He is shorter but faster.","B":"He is taller and slower.","C":"He is shorter and slower.","D":"We have exactly the same height and speed."},"A","The sentence gives two comparisons: younger brother is shorter in height and faster in running.","Track each comparative adjective separately and preserve the contrast between the two dimensions.",["Identify the height comparison: shorter than me.","Identify the speed comparison: runs faster.","Combine both facts without treating but as a contradiction.","Reject choices that reverse either comparison.","Select A because it matches both comparative statements."],"medium"),
make(9,"My aunt moved to a new city. I call her every Sunday and send photos of our garden. What is the main idea?",{"A":"I keep in touch with a family member who lives far away.","B":"I moved to the new city every Sunday.","C":"My aunt grows our garden at school.","D":"We stopped communicating after she moved."},"A","Weekly calls and shared photos show continued contact with the aunt after she moved away.","Combine the repeated action and the reason for it to form the relationship-level main idea.",["Identify the relationship: aunt and speaker.","Notice the distance: she moved to a new city.","Collect the contact actions: calls and photos.","Reject movement, school gardening, and stopped contact claims.","Choose A because it summarizes the ongoing relationship."],"medium"),
make(10,"A description says: 'Jordan is my friend. He is careful with his words, listens before answering, and remembers small details about people.' What is the best respectful summary?",{"A":"Jordan seems thoughtful and considerate.","B":"Jordan is certainly dishonest.","C":"Jordan never listens to anyone.","D":"Jordan's appearance is the only important fact."},"A","Careful speech, listening, and remembering details support a thoughtful and considerate description; A avoids an unsupported judgment.","Summarize repeated behaviors as a modest personality inference and avoid claims not evidenced by the description.",["List the observed behaviors rather than guessing a label immediately.","Connect careful speech and listening with thoughtfulness.","Connect remembering details with consideration for others.","Reject dishonest, never listens, and appearance-only claims as unsupported.","Choose A because it is respectful and evidence-based."],"hard"),
]
for q in Q:(OUT/f"{q['id']}.json").write_text(json.dumps(q,ensure_ascii=False,indent=2)+"\n")
